// Datos SATI Casa Matriz CDE (recepcion-cde.csv) y Monitoreo de Depósito Danesa
import {
  collapseSpacesTrim,
  createEmptyDepurationStats,
  detectSatiSheetScope,
  evaluateRawSatiRow,
  isSameNormalizedText,
  mergeDepurationStats,
  mergeSatiDuplicateFields,
  normalizeSatiRowFields,
  SATI_MIN_ID_CDE,
  yieldToBrowser,
  type SatiDepurationStats,
  type SatiPreparedSheetInput,
  type SatiSheetScope,
} from '../lib/satiRawDepurator';

export interface RecepcionCdeTicket {
  idOrden: string;
  codigoProducto: string;
  cliente: string;
  mensaje: string;
  fechaIngreso: string;
  fechaEntregada?: string;
  fechaEntregadaAsu?: string;
  fechaVenta?: string;
  estado: string;
  tipoComponente: string;
  modelo: string;
  marca: string;
  serial: string;
  accesorios?: string;
  // Campos calculados y operativos de depósito
  diasResolucion?: number | null;
  esDanesa?: boolean;
  recibidoEnDeposito?: boolean;
  fechaRecibidoDeposito?: string;
  esEstadoCambiadoReciente?: boolean;
  esNuevoIngreso?: boolean;
  // Cruce de datos con Recepción ASU
  idOrdenAsu?: string;
  idOrdenCde?: string;
  clienteAsu?: string;
  fechaIngresoAsu?: string;
  fechaIngresoCde?: string;
  estadoAsu?: string;
  estadoCde?: string;
  matchReason?: string;
  origen?: "ASU" | "CDE";
  rowKey?: string;
}

function normalizeDateYear(rawYear: string): number {
  const y = parseInt(rawYear, 10);
  if (isNaN(y)) return NaN;
  if (rawYear.length <= 2) {
    return y <= 70 ? 2000 + y : 1900 + y;
  }
  return y;
}

export function parseFechaDMY(str?: string): Date | null {
  if (!str) return null;
  const clean = str.trim().split(/[\sT]/)[0];
  if (!clean) return null;

  const sep = clean.includes('-') ? '-' : clean.includes('/') ? '/' : clean.includes('.') ? '.' : null;
  if (!sep) return null;

  const parts = clean.split(sep);
  if (parts.length !== 3) return null;

  let d: number;
  let m: number;
  let y: number;

  if (parts[0].length === 4) {
    // YYYY-MM-DD o YYYY/MM/DD
    y = parseInt(parts[0], 10);
    m = parseInt(parts[1], 10) - 1;
    d = parseInt(parts[2], 10);
  } else {
    // DD/MM/YYYY, DD/MM/YY, DD-MM-YYYY o DD.MM.YYYY
    d = parseInt(parts[0], 10);
    m = parseInt(parts[1], 10) - 1;
    y = normalizeDateYear(parts[2]);
  }

  if (isNaN(d) || isNaN(m) || isNaN(y) || m < 0 || m > 11 || d < 1 || d > 31) return null;
  return new Date(y, m, d);
}

export function calcularDiasResolucion(fechaIngreso?: string, fechaEntregada?: string): number | null {
  const fi = parseFechaDMY(fechaIngreso);
  const fe = parseFechaDMY(fechaEntregada);
  if (!fi || !fe) return null;
  const diffTime = fe.getTime() - fi.getTime();
  const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));
  return diffDays >= 0 ? diffDays : null;
}

/**
 * Valida si un despacho en CDE es cronológicamente coherente con el ingreso en ASU.
 * Un equipo jamás puede haber sido despachado en CDE antes de ingresar a ASU.
 * Se permite una tolerancia máxima de 1 día por diferencias horarias o registros al cierre de jornada.
 */
export function isDespachoCoherente(fechaIngreso?: string, fechaDespacho?: string): boolean {
  if (!fechaIngreso || !fechaDespacho) return true;
  const fi = parseFechaDMY(fechaIngreso);
  const fd = parseFechaDMY(fechaDespacho);
  if (!fi || !fd) return true;
  const diffMs = fd.getTime() - fi.getTime();
  const diffDays = diffMs / (1000 * 60 * 60 * 24);
  return diffDays >= -1;
}

export function isTicketDanesa(cliente?: string): boolean {
  if (!cliente) return false;
  return cliente.toLowerCase().includes('danesa');
}

/**
 * Estados internos/operativos que no corresponden a clientes finales en Clientes ASU:
 * - Enviado a destruccion / Enviado Destruccion
 * - Enviado a stock / Enviado Stock
 * - Liquidacion / Liquidación
 * - Vendido / Vendida
 */
export function isEstadoInternoNoCliente(estado?: string): boolean {
  if (!estado) return false;
  const norm = estado
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
  if (!norm) return false;

  return (
    norm.includes('destruccion') ||
    (norm.includes('enviado') && norm.includes('stock')) ||
    norm.includes('liquidacion') ||
    /\bvendid[oa]\b/.test(norm)
  );
}

export interface SatiCsvClassification {
  asuRows: RecepcionCdeTicket[];
  cdeRows: RecepcionCdeTicket[];
  totalRows: number;
  depurationStats: SatiDepurationStats;
  reconcileFullAsu?: boolean;
}

/**
 * Parsea y depura automáticamente un archivo CSV/Excel exportado de SATI:
 * - Filtra históricos (< 29403 en ASU, < 125600 en CDE)
 * - Excluye palabras de cliente ('drop', 'emap', '10807', 'code 100 sa', 'farma 10', 'dream', 'drem', 'py-pjc', 'py-sg', 'py/sg')
 * - Excluye paréntesis distintos a (JC) y (ATCN) en cliente
 * - Deduplica órdenes repetidas conservando los datos más completos
 * - Normaliza cliente, marca, modelo, serial y tipoComponente
 */
function parseAndDepurateSatiCsvRows(
  csvContent: string,
  explicitScope?: SatiSheetScope
): {
  rows: RecepcionCdeTicket[];
  stats: SatiDepurationStats;
  scope: SatiSheetScope;
} {
  const stats = createEmptyDepurationStats();
  const cleanText = csvContent.replace(/^\uFEFF/, '').trim();
  if (!cleanText) return { rows: [], stats, scope: explicitScope || 'MIXED' };

  // Detección automática del delimitador principal en las primeras 5 líneas
  const firstLineEnd = cleanText.indexOf('\n');
  const firstLine = firstLineEnd !== -1 ? cleanText.slice(0, firstLineEnd) : cleanText;
  const semicolonCount = (firstLine.match(/;/g) || []).length;
  const commaCount = (firstLine.match(/,/g) || []).length;
  const tabCount = (firstLine.match(/\t/g) || []).length;

  let delimiter = ',';
  if (semicolonCount > commaCount && semicolonCount > tabCount) {
    delimiter = ';';
  } else if (tabCount > commaCount && tabCount > semicolonCount) {
    delimiter = '\t';
  }

  // Parser robusto de celdas con soporte de comillas y saltos de línea internos
  const rows: string[][] = [];
  let currentRow: string[] = [];
  let currentCell = '';
  let inQuotes = false;

  for (let i = 0; i < cleanText.length; i++) {
    const char = cleanText[i];
    const nextChar = cleanText[i + 1];

    if (inQuotes) {
      if (char === '"' && nextChar === '"') {
        currentCell += '"';
        i++;
      } else if (char === '"') {
        inQuotes = false;
      } else {
        currentCell += char;
      }
    } else {
      if (char === '"') {
        inQuotes = true;
      } else if (char === delimiter) {
        currentRow.push(currentCell.trim());
        currentCell = '';
      } else if (char === '\r' && nextChar === '\n') {
        currentRow.push(currentCell.trim());
        if (currentRow.some((c) => c !== '')) {
          rows.push(currentRow);
        }
        currentRow = [];
        currentCell = '';
        i++;
      } else if (char === '\n' || char === '\r') {
        currentRow.push(currentCell.trim());
        if (currentRow.some((c) => c !== '')) {
          rows.push(currentRow);
        }
        currentRow = [];
        currentCell = '';
      } else {
        currentCell += char;
      }
    }
  }

  if (currentCell.length > 0 || currentRow.length > 0) {
    currentRow.push(currentCell.trim());
    if (currentRow.some((c) => c !== '')) {
      rows.push(currentRow);
    }
  }

  const dedupMap = new Map<string, RecepcionCdeTicket>();
  let colMap: Record<string, number> = {
    idOrden: 0,
    codigoProducto: 1,
    cliente: 2,
    mensaje: 3,
    fechaIngreso: 4,
    fechaEntregada: 5,
    fechaTransportadora: -1,
    fechaVenta: 6,
    estado: 7,
    tipoComponente: 8,
    marca: 9,
    modelo: 10,
    serial: 11,
  };
  let headerDetected = false;
  let resolvedScope: SatiSheetScope | undefined = explicitScope;

  for (let i = 0; i < rows.length; i++) {
    const cells = rows[i];
    if (cells.length < 2) continue;

    // Detección dinámica y robusta de cabecera (soporta filas de título previas en XLSX/CSV)
    if (!headerDetected && i < 6 && stats.totalRawFilas === 0) {
      const headerIndex: Record<string, number> = {};
      cells.forEach((header, idx) => {
        const h = header
          .toLowerCase()
          .normalize("NFD")
          .replace(/[\u0300-\u036f]/g, "")
          .replace(/[^a-z0-9]/g, "");

        if (
          h.includes("idorden") ||
          h === "orden" ||
          h === "id" ||
          h === "nroorden" ||
          h === "norden" ||
          h === "nrodeorden" ||
          h === "ticket"
        ) {
          headerIndex.idOrden = idx;
        } else if (h.includes("codigo") || h === "cod" || h.includes("sku") || h === "codproducto" || h === "producto") {
          if (headerIndex.codigoProducto === undefined) headerIndex.codigoProducto = idx;
        } else if (h.includes("cliente") || h.includes("titular")) {
          if (headerIndex.cliente === undefined) headerIndex.cliente = idx;
        } else if (h.includes("mensaje") || h.includes("obs") || h.includes("dictamen") || h.includes("falla")) {
          if (headerIndex.mensaje === undefined) headerIndex.mensaje = idx;
        } else if (h.includes("fechaingreso") || h.includes("fechadeingreso") || h === "ingreso" || h.includes("fechaentrada") || h.includes("fecharecepcion")) {
          if (headerIndex.fechaIngreso === undefined) headerIndex.fechaIngreso = idx;
        } else if (
          h.includes("fechatransport") ||
          h.includes("ftransport") ||
          h.includes("despachotransp") ||
          h === "transportadora" ||
          h.includes("enviotransp")
        ) {
          if (headerIndex.fechaTransportadora === undefined) headerIndex.fechaTransportadora = idx;
        } else if (
          h.includes("fechaentreg") ||
          h.includes("fechadeentreg") ||
          h.includes("fentreg") ||
          h === "entrega" ||
          h === "entregada" ||
          h === "entregado" ||
          h.includes("fechadespacho") ||
          h === "despacho" ||
          h.includes("fechasalida") ||
          h.includes("fechaenvio") ||
          h.includes("fecharetiro")
        ) {
          if (headerIndex.fechaEntregada === undefined) headerIndex.fechaEntregada = idx;
        } else if (h.includes("fechaventa") || h.includes("fechadeventa") || h === "venta" || h.includes("fechafactura")) {
          if (headerIndex.fechaVenta === undefined) headerIndex.fechaVenta = idx;
        } else if (h.includes("estado") || h === "status" || h === "situacion") {
          if (headerIndex.estado === undefined) headerIndex.estado = idx;
        } else if (h.includes("componente") || h.includes("categoria") || h.includes("tipo")) {
          if (headerIndex.tipoComponente === undefined) headerIndex.tipoComponente = idx;
        } else if (h.includes("marca")) {
          if (headerIndex.marca === undefined) headerIndex.marca = idx;
        } else if (h.includes("modelo")) {
          if (headerIndex.modelo === undefined) headerIndex.modelo = idx;
        } else if (h.includes("serial") || h === "serie" || h === "sn" || h.includes("nroserie") || h.includes("numeroserie")) {
          if (headerIndex.serial === undefined) headerIndex.serial = idx;
        }
      });

      const maybeOrderCell = (cells[headerIndex.idOrden ?? 0] || "").trim();
      const hasSemanticHeader =
        Object.keys(headerIndex).length >= 2 &&
        (headerIndex.idOrden !== undefined || headerIndex.cliente !== undefined || headerIndex.estado !== undefined) &&
        !/^#?\d+$/.test(maybeOrderCell);

      if (hasSemanticHeader) {
        headerDetected = true;
        colMap = {
          idOrden: headerIndex.idOrden ?? 0,
          codigoProducto: headerIndex.codigoProducto ?? -1,
          cliente: headerIndex.cliente ?? -1,
          mensaje: headerIndex.mensaje ?? -1,
          fechaIngreso: headerIndex.fechaIngreso ?? -1,
          fechaEntregada: headerIndex.fechaEntregada ?? headerIndex.fechaTransportadora ?? -1,
          fechaTransportadora: headerIndex.fechaTransportadora ?? -1,
          fechaVenta: headerIndex.fechaVenta ?? -1,
          estado: headerIndex.estado ?? -1,
          tipoComponente: headerIndex.tipoComponente ?? -1,
          marca: headerIndex.marca ?? -1,
          modelo: headerIndex.modelo ?? -1,
          serial: headerIndex.serial ?? -1,
        };
        continue;
      }
    }

    const getVal = (field: keyof typeof colMap) => {
      const idx = colMap[field];
      return idx !== undefined && idx >= 0 && cells[idx] !== undefined ? cells[idx].trim() : '';
    };

    const rawId = getVal('idOrden').replace(/^#/, '');
    if (!rawId) continue;
    if (!headerDetected && i < 5 && !/\d/.test(rawId)) continue;

    if (!resolvedScope) {
      const idIdx = colMap.idOrden;
      resolvedScope = detectSatiSheetScope(
        (function* () {
          for (let k = i; k < rows.length; k++) {
            yield rows[k]?.[idIdx];
          }
        })()
      );
    }

    const rawCliente = getVal('cliente');
    const evaluation = evaluateRawSatiRow(rawId, rawCliente, resolvedScope);
    if (evaluation.reason === 'SIN_ID') continue;

    stats.totalRawFilas++;

    if (!evaluation.keep) {
      if (
        evaluation.reason === 'ID_HISTORICO_ASU'
      ) {
        stats.descartadasHistoricasAsu++;
      } else if (evaluation.reason === 'ID_HISTORICO_CDE') {
        stats.descartadasHistoricasCde++;
      } else if (evaluation.reason === 'PALABRA_EXCLUIDA') {
        stats.descartadasFiltroCliente++;
      } else if (evaluation.reason === 'PARENTESIS_EXCLUIDO') {
        stats.descartadasParentesis++;
      }
      continue;
    }

    const idOrden = evaluation.cleanId;
    const codigoProducto = collapseSpacesTrim(getVal('codigoProducto'));
    const rawMensaje = getVal('mensaje');
    const fechaIngreso = collapseSpacesTrim(getVal('fechaIngreso'));
    const primaryFechaEntregada = collapseSpacesTrim(getVal('fechaEntregada'));
    const fallbackFechaTransportadora = collapseSpacesTrim(getVal('fechaTransportadora'));
    const fechaEntregada = isFechaValida(primaryFechaEntregada)
      ? primaryFechaEntregada
      : isFechaValida(fallbackFechaTransportadora)
        ? fallbackFechaTransportadora
        : primaryFechaEntregada;
    const fechaVenta = collapseSpacesTrim(getVal('fechaVenta'));
    const estado = collapseSpacesTrim(getVal('estado')) || 'En Asignacion';
    const rawTipoComponente = getVal('tipoComponente') || 'GENERAL';
    const rawMarca = getVal('marca');
    const rawModelo = getVal('modelo');
    const rawSerial = getVal('serial');

    const { normalized, camposModificados } = normalizeSatiRowFields({
      cliente: rawCliente,
      marca: rawMarca,
      modelo: rawModelo,
      serial: rawSerial,
      tipoComponente: rawTipoComponente,
      mensaje: rawMensaje,
    });
    stats.camposNormalizados += camposModificados;

    const cleanTicket: RecepcionCdeTicket = {
      idOrden,
      codigoProducto,
      cliente: normalized.cliente,
      mensaje: normalized.mensaje,
      fechaIngreso,
      fechaEntregada,
      fechaVenta,
      estado,
      tipoComponente: normalized.tipoComponente || 'General',
      modelo: normalized.modelo,
      marca: normalized.marca,
      serial: normalized.serial,
      diasResolucion: calcularDiasResolucion(fechaIngreso, fechaEntregada),
      esDanesa: isTicketDanesa(normalized.cliente),
      origen: evaluation.origen,
    };

    const dedupKey = `${evaluation.origen}:${idOrden}`;
    const prev = dedupMap.get(dedupKey);
    if (prev) {
      const merged = mergeSatiDuplicateFields(prev, cleanTicket);
      merged.diasResolucion = calcularDiasResolucion(merged.fechaIngreso, merged.fechaEntregada);
      merged.esDanesa = isTicketDanesa(merged.cliente);
      merged.origen = evaluation.origen;
      dedupMap.set(dedupKey, merged);
      stats.duplicadosFusionados++;
    } else {
      dedupMap.set(dedupKey, cleanTicket);
    }
  }

  const rowsClean = Array.from(dedupMap.values());
  stats.totalValidas = rowsClean.length;
  return { rows: rowsClean, stats, scope: resolvedScope || 'MIXED' };
}

export function classifyAndParseSatiCsv(
  csvContent: string,
  explicitScope?: SatiSheetScope
): SatiCsvClassification {
  const { rows: allRows, stats, scope } = parseAndDepurateSatiCsvRows(csvContent, explicitScope);
  const asuRows: RecepcionCdeTicket[] = [];
  const cdeRows: RecepcionCdeTicket[] = [];

  for (const row of allRows) {
    if (row.origen === 'ASU') {
      asuRows.push(row);
    } else {
      cdeRows.push({ ...row, origen: 'CDE' });
    }
  }

  return {
    asuRows,
    cdeRows,
    totalRows: asuRows.length + cdeRows.length,
    depurationStats: stats,
    reconcileFullAsu:
      scope === 'ASU' && stats.descartadasHistoricasAsu >= 1000 && asuRows.length >= 200,
  };
}

function mergeClassifiedPartIntoMaps(
  part: SatiCsvClassification,
  asuMap: Map<string, RecepcionCdeTicket>,
  cdeMap: Map<string, RecepcionCdeTicket>,
  stats: SatiDepurationStats,
  preSkippedAsu = 0,
  preSkippedCde = 0
): SatiDepurationStats {
  let updated = mergeDepurationStats(stats, part.depurationStats);
  const preTotal = preSkippedAsu + preSkippedCde;
  if (preTotal > 0) {
    updated.totalRawFilas += preTotal;
    updated.descartadasHistoricasAsu += preSkippedAsu;
    updated.descartadasHistoricasCde += preSkippedCde;
  }

  for (const row of part.asuRows) {
    const prev = asuMap.get(row.idOrden);
    if (prev) {
      const merged = mergeSatiDuplicateFields(prev, row);
      merged.diasResolucion = calcularDiasResolucion(merged.fechaIngreso, merged.fechaEntregada);
      merged.esDanesa = isTicketDanesa(merged.cliente);
      merged.origen = 'ASU';
      asuMap.set(row.idOrden, merged);
      updated.duplicadosFusionados++;
    } else {
      asuMap.set(row.idOrden, row);
    }
  }

  for (const row of part.cdeRows) {
    const prev = cdeMap.get(row.idOrden);
    if (prev) {
      const merged = mergeSatiDuplicateFields(prev, row);
      merged.diasResolucion = calcularDiasResolucion(merged.fechaIngreso, merged.fechaEntregada);
      merged.esDanesa = isTicketDanesa(merged.cliente);
      merged.origen = 'CDE';
      cdeMap.set(row.idOrden, merged);
      updated.duplicadosFusionados++;
    } else {
      cdeMap.set(row.idOrden, row);
    }
  }

  return updated;
}

/**
 * Consolida y depura múltiples archivos u hojas Excel/CSV SATI cargados a la vez
 * (por ejemplo, ASU.xlsx + CDE.xlsx en una sola selección), unificando estadísticas
 * y fusionando posibles órdenes repetidas entre archivos.
 */
export function classifyAndParseMultiSatiCsv(csvContents: string[]): SatiCsvClassification {
  if (csvContents.length === 0) {
    return {
      asuRows: [],
      cdeRows: [],
      totalRows: 0,
      depurationStats: createEmptyDepurationStats(),
    };
  }
  if (csvContents.length === 1) {
    return classifyAndParseSatiCsv(csvContents[0]);
  }

  const asuMap = new Map<string, RecepcionCdeTicket>();
  const cdeMap = new Map<string, RecepcionCdeTicket>();
  let stats = createEmptyDepurationStats();

  for (const content of csvContents) {
    if (!content || !content.trim()) continue;
    const part = classifyAndParseSatiCsv(content);
    stats = mergeClassifiedPartIntoMaps(part, asuMap, cdeMap, stats);
  }

  const asuRows = Array.from(asuMap.values());
  const cdeRows = Array.from(cdeMap.values());
  stats.totalValidas = asuRows.length + cdeRows.length;

  return {
    asuRows,
    cdeRows,
    totalRows: stats.totalValidas,
    depurationStats: stats,
  };
}

/**
 * Versión asíncrona no bloqueante para archivos masivos (32k ASU + 130k CDE simultáneos):
 * procesa cada hoja pre-filtrada cediendo el hilo entre archivos y suma los contadores históricos.
 */
export async function classifyAndParseMultiSatiPreparedAsync(
  inputs: SatiPreparedSheetInput[]
): Promise<SatiCsvClassification> {
  if (inputs.length === 0) {
    return {
      asuRows: [],
      cdeRows: [],
      totalRows: 0,
      depurationStats: createEmptyDepurationStats(),
    };
  }

  const asuMap = new Map<string, RecepcionCdeTicket>();
  const cdeMap = new Map<string, RecepcionCdeTicket>();
  let stats = createEmptyDepurationStats();
  let sawFullRawAsu = false;

  for (const input of inputs) {
    await yieldToBrowser();
    const part =
      input.csvText && input.csvText.trim()
        ? classifyAndParseSatiCsv(input.csvText, input.scope)
        : {
            asuRows: [],
            cdeRows: [],
            totalRows: 0,
            depurationStats: createEmptyDepurationStats(),
          };
    if (
      (input.scope === 'ASU' || part.reconcileFullAsu) &&
      input.preSkippedHistoricasAsu + part.depurationStats.descartadasHistoricasAsu >= 1000 &&
      part.asuRows.length >= 200
    ) {
      sawFullRawAsu = true;
    }
    stats = mergeClassifiedPartIntoMaps(
      part,
      asuMap,
      cdeMap,
      stats,
      input.preSkippedHistoricasAsu,
      input.preSkippedHistoricasCde
    );
  }

  const asuRows = Array.from(asuMap.values());
  const cdeRows = Array.from(cdeMap.values());
  stats.totalValidas = asuRows.length + cdeRows.length;

  return {
    asuRows,
    cdeRows,
    totalRows: stats.totalValidas,
    depurationStats: stats,
    reconcileFullAsu: sawFullRawAsu,
  };
}

export function parseRecepcionCdeCSV(csvContent: string): RecepcionCdeTicket[] {
  return classifyAndParseSatiCsv(csvContent).cdeRows;
}

// v3: invalida la caché anterior que tenía columnas desplazadas por comas dentro del Mensaje
export const CDE_STORAGE_KEY = 'nissei_recepcion_cde_data_v3';

export function isFechaValida(str?: string): boolean {
  if (!str) return false;
  const t = str.trim();
  const hasDatePattern =
    /^\d{1,2}\/\d{1,2}\/\d{2,4}/.test(t) ||
    /^\d{4}[-/]\d{1,2}[-/]\d{1,2}/.test(t) ||
    /^\d{1,2}[-.]\d{1,2}[-.]\d{2,4}/.test(t);
  if (!hasDatePattern) return false;
  const parsed = parseFechaDMY(t);
  return parsed !== null && !Number.isNaN(parsed.getTime()) && parsed.getFullYear() >= 2000;
}
export const CDE_CHECKINS_KEY = 'nissei_deposito_cde_checkins_v1';
export const SATI_OVERRIDES_KEY = 'nissei_sati_ticket_overrides_v1';

export interface SatiCheckinData {
  recibido: boolean;
  fecha: string;
}

export function getStoredCdeCheckins(): Record<string, SatiCheckinData> {
  if (typeof window === 'undefined') return {};
  try {
    const raw = localStorage.getItem(CDE_CHECKINS_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    const result: Record<string, SatiCheckinData> = {};
    for (const [k, v] of Object.entries(parsed)) {
      if (typeof v === 'boolean') {
        result[k] = { recibido: v, fecha: "" };
      } else if (v && typeof v === 'object') {
        result[k] = {
          recibido: Boolean((v as any).recibido),
          fecha: (v as any).fecha || "",
        };
      }
    }
    return result;
  } catch {
    return {};
  }
}

export interface SatiTicketOverride {
  idOrdenAsu?: string;
  idOrdenCde?: string;
  fechaIngresoAsu?: string;
  fechaIngresoCde?: string;
  fechaDespachoCde?: string;
  fechaRecibidoAsu?: string;
}

export function getStoredSatiOverrides(): Record<string, SatiTicketOverride> {
  if (typeof window === 'undefined') return {};
  try {
    const raw = localStorage.getItem(SATI_OVERRIDES_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

export function saveSatiTicketOverride(key: string, override: SatiTicketOverride): void {
  if (typeof window === 'undefined') return;
  try {
    const overrides = getStoredSatiOverrides();
    overrides[key] = { ...(overrides[key] || {}), ...override };
    localStorage.setItem(SATI_OVERRIDES_KEY, JSON.stringify(overrides));
  } catch (e) {
    console.error('Error al guardar override SATI:', e);
  }
}

const SATI_CROSS_MATCHES_KEY = 'nissei_sati_cross_matches';

export function getStoredSatiCrossMatches(): Array<{ idOrdenAsu: string; idOrdenCde: string }> {
  if (typeof window === 'undefined') return [];
  try {
    const raw = localStorage.getItem(SATI_CROSS_MATCHES_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

export function saveSatiCrossMatchLocal(idOrdenAsu: string, idOrdenCde: string): void {
  if (typeof window === 'undefined') return;
  try {
    const list = getStoredSatiCrossMatches().filter(
      (m) => m.idOrdenAsu !== idOrdenAsu && m.idOrdenCde !== idOrdenCde
    );
    list.push({ idOrdenAsu: idOrdenAsu.trim(), idOrdenCde: idOrdenCde.trim() });
    localStorage.setItem(SATI_CROSS_MATCHES_KEY, JSON.stringify(list));
  } catch (e) {
    console.error('Error al guardar cruce SATI local:', e);
  }
}

export function removeSatiCrossMatchLocal(idOrdenAsu: string, idOrdenCde: string): void {
  if (typeof window === 'undefined') return;
  try {
    const list = getStoredSatiCrossMatches().filter(
      (m) => !(m.idOrdenAsu === idOrdenAsu && m.idOrdenCde === idOrdenCde)
    );
    localStorage.setItem(SATI_CROSS_MATCHES_KEY, JSON.stringify(list));
  } catch (e) {
    console.error('Error al eliminar cruce SATI local:', e);
  }
}

export function replaceSatiCrossMatchesLocal(
  list: Array<{ idOrdenAsu: string; idOrdenCde: string }>
): void {
  if (typeof window === 'undefined' || !Array.isArray(list)) return;
  try {
    const sanitized = list
      .filter((m) => m && m.idOrdenAsu && m.idOrdenCde)
      .map((m) => ({
        idOrdenAsu: String(m.idOrdenAsu).trim(),
        idOrdenCde: String(m.idOrdenCde).trim(),
      }));
    localStorage.setItem(SATI_CROSS_MATCHES_KEY, JSON.stringify(sanitized));
  } catch (e) {
    console.error('Error al sincronizar cruces SATI locales:', e);
  }
}

export function applyCloudCdeCheckins(
  cloudCheckins?: Record<string, SatiCheckinData> | null
): Record<string, SatiCheckinData> {
  if (typeof window === 'undefined' || !cloudCheckins || typeof cloudCheckins !== 'object') {
    return getStoredCdeCheckins();
  }
  try {
    const normalized: Record<string, SatiCheckinData> = {};
    for (const [k, v] of Object.entries(cloudCheckins)) {
      if (typeof v === 'boolean') {
        normalized[k] = { recibido: v, fecha: '' };
      } else if (v && typeof v === 'object') {
        normalized[k] = {
          recibido: Boolean((v as SatiCheckinData).recibido),
          fecha: String((v as SatiCheckinData).fecha || ''),
        };
      }
    }
    localStorage.setItem(CDE_CHECKINS_KEY, JSON.stringify(normalized));
    return normalized;
  } catch (e) {
    console.error('Error al guardar checkins CDE de nube:', e);
    return getStoredCdeCheckins();
  }
}

export function applyCloudCdeTickets(
  rawData: RecepcionCdeTicket[],
  cloudCheckins?: Record<string, SatiCheckinData> | null,
  cloudCrossMatches?: Array<{ idOrdenAsu: string; idOrdenCde: string }> | null
): RecepcionCdeTicket[] {
  const checkins = cloudCheckins ? applyCloudCdeCheckins(cloudCheckins) : getStoredCdeCheckins();
  if (Array.isArray(cloudCrossMatches)) {
    replaceSatiCrossMatchesLocal(cloudCrossMatches);
  }

  const enriched: RecepcionCdeTicket[] = rawData
    .filter((t: RecepcionCdeTicket) => {
      const num = parseInt(t.idOrden, 10);
      return isNaN(num) || num >= 100000;
    })
    .map((t: RecepcionCdeTicket, idx: number) => {
      const rowKey = t.rowKey || `CDE_${t.idOrden}_${t.codigoProducto || ''}_${t.serial || ''}_${idx}`;
      const checkinInfo = checkins[rowKey] || checkins[t.idOrden];
      const isRecibido = checkinInfo ? checkinInfo.recibido : Boolean(t.recibidoEnDeposito);
      return {
        ...t,
        rowKey,
        diasResolucion: t.diasResolucion ?? calcularDiasResolucion(t.fechaIngreso, t.fechaEntregada),
        esDanesa: isTicketDanesa(t.cliente),
        recibidoEnDeposito: isRecibido,
        fechaRecibidoDeposito: checkinInfo?.fecha || t.fechaRecibidoDeposito,
      };
    });

  saveCdeTickets(enriched);
  return enriched;
}

export function getStoredCdeTickets(): RecepcionCdeTicket[] {
  if (typeof window === 'undefined') return INITIAL_RECEPCION_CDE_DATA;
  try {
    const raw = localStorage.getItem(CDE_STORAGE_KEY);
    const checkins = getStoredCdeCheckins();

    const base = raw ? JSON.parse(raw) : INITIAL_RECEPCION_CDE_DATA;
    return base
      .filter((t: RecepcionCdeTicket) => {
        const num = parseInt(t.idOrden, 10);
        return isNaN(num) || num >= 100000;
      })
      .map((t: RecepcionCdeTicket, idx: number) => {
        const rowKey = t.rowKey || `CDE_${t.idOrden}_${t.codigoProducto || ''}_${t.serial || ''}_${idx}`;
        const checkinInfo = checkins[rowKey] || checkins[t.idOrden];
        const isRecibido = checkinInfo ? checkinInfo.recibido : Boolean(t.recibidoEnDeposito);
        return {
          ...t,
          rowKey,
          diasResolucion: t.diasResolucion ?? calcularDiasResolucion(t.fechaIngreso, t.fechaEntregada),
          esDanesa: isTicketDanesa(t.cliente),
          recibidoEnDeposito: isRecibido,
          fechaRecibidoDeposito: checkinInfo?.fecha || t.fechaRecibidoDeposito,
        };
      });
  } catch (e) {
    console.error('Error al leer tickets CDE de localStorage:', e);
    return INITIAL_RECEPCION_CDE_DATA;
  }
}

export function saveCdeTickets(tickets: RecepcionCdeTicket[]): void {
  if (typeof window === 'undefined') return;
  try {
    // Asegurar que solo órdenes de CDE (>= 100000) se guarden
    const filtered = tickets.filter((t) => {
      const num = parseInt(t.idOrden, 10);
      return isNaN(num) || num >= 100000;
    });
    localStorage.setItem(CDE_STORAGE_KEY, JSON.stringify(filtered));
  } catch (e) {
    console.error('Error al guardar tickets CDE:', e);
  }
}

export async function fetchCdeTicketsFromMySQL(options?: {
  throwOnError?: boolean;
}): Promise<RecepcionCdeTicket[]> {
  try {
    const res = await fetch("/api/db?module=cde", { cache: "no-store" });
    const json = await res.json().catch(() => null);
    if (!res.ok || !json?.ok) {
      throw new Error(json?.error || `Error MySQL CDE (HTTP ${res.status})`);
    }
    if (json.ok && Array.isArray(json.data) && json.data.length > 0) {
      return applyCloudCdeTickets(
        json.data as RecepcionCdeTicket[],
        json.checkins || null,
        Array.isArray(json.crossMatches) ? json.crossMatches : null
      );
    }
  } catch (err) {
    console.warn("[MySQL Sync CDE] Usando caché local:", err);
    if (options?.throwOnError) {
      throw err instanceof Error ? err : new Error("Error al conectar con MySQL CDE.");
    }
  }
  return getStoredCdeTickets();
}

export function toggleCheckinDeposito(
  targetKey: string,
  extraIds?: { idOrden?: string; idOrdenAsu?: string; idOrdenCde?: string } | string,
  explicitState?: boolean,
  explicitFecha?: string
): { recibido: boolean; fecha: string } {
  if (typeof window === 'undefined') return { recibido: false, fecha: '' };
  try {
    const checkins = getStoredCdeCheckins();
    const current = checkins[targetKey] ? checkins[targetKey].recibido : false;
    const newState = explicitState !== undefined ? explicitState : !current;
    const todayStr =
      explicitFecha ||
      new Date().toLocaleDateString("es-PY", {
        day: "2-digit",
        month: "2-digit",
        year: "numeric",
      });

    const checkinData: SatiCheckinData = {
      recibido: newState,
      fecha: newState ? todayStr : "",
    };
    checkins[targetKey] = checkinData;
    localStorage.setItem(CDE_CHECKINS_KEY, JSON.stringify(checkins));

    const idParams =
      typeof extraIds === "string"
        ? { idOrden: extraIds }
        : extraIds || { idOrden: targetKey };

    // Sincronizar directamente con MySQL
    fetch('/api/db', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'TOGGLE_CDE_CHECKIN',
        idOrden: idParams.idOrden || targetKey,
        idOrdenAsu: idParams.idOrdenAsu,
        idOrdenCde: idParams.idOrdenCde,
        targetKey,
        recibidoEnDeposito: newState,
        fechaRecibido: checkinData.fecha,
      }),
    }).catch((err) => console.error('[MySQL Error Toggle CDE Checkin]', err));

    return checkinData;
  } catch (e) {
    console.error('Error al actualizar checkin en depósito:', e);
    return { recibido: false, fecha: '' };
  }
}

export interface CambioEstadoCde {
  idOrden: string;
  cliente: string;
  equipo: string;
  estadoAnterior: string;
  estadoNuevo: string;
  fechaEntregada?: string;
  esDanesa: boolean;
  enTransito: boolean;
}

export interface ResultadoCargaCdeCSV {
  updatedTickets: RecepcionCdeTicket[];
  totalFilasLeidas: number;
  totalActualizadas: number;
  totalNuevas: number;
  totalSinCambios: number;
  totalEnTransitoNuevos: number;
  cambios: CambioEstadoCde[];
  changedOrNewTickets?: RecepcionCdeTicket[];
  depurationStats?: SatiDepurationStats;
}

export function procesarActualizacionCdeCSV(
  csvContent: string | SatiCsvClassification,
  currentTickets: RecepcionCdeTicket[],
  options?: { skipBackgroundSync?: boolean }
): ResultadoCargaCdeCSV {
  const classified =
    typeof csvContent === 'string' ? classifyAndParseSatiCsv(csvContent) : csvContent;
  const incoming = classified.cdeRows;
  const currentMap = new Map<string, RecepcionCdeTicket>();
  currentTickets
    .filter((t) => {
      const num = parseInt(t.idOrden, 10);
      return isNaN(num) || num >= SATI_MIN_ID_CDE;
    })
    .forEach((t) => currentMap.set(t.idOrden, t));

  const checkinsRaw = typeof window !== 'undefined' ? localStorage.getItem(CDE_CHECKINS_KEY) : null;
  const checkins: Record<string, boolean> = checkinsRaw ? JSON.parse(checkinsRaw) : {};

  const cambios: CambioEstadoCde[] = [];
  const updatedList: RecepcionCdeTicket[] = [];
  const changedOrNewTickets: RecepcionCdeTicket[] = [];
  const seenIds = new Set<string>();

  let totalSinCambios = 0;
  let totalEnTransitoNuevos = 0;

  for (const inc of incoming) {
    seenIds.add(inc.idOrden);
    const existing = currentMap.get(inc.idOrden);
    const isEntregada = inc.estado.toLowerCase().includes('entregada');
    const esDanesa = inc.esDanesa || isTicketDanesa(inc.cliente);
    const esReparada = (existing?.estadoAsu || '').toLowerCase().includes('reparada') || inc.estado.toLowerCase().includes('reparada');
    const tieneDetalleRep = Boolean(
      (inc.mensaje || existing?.mensaje || '').toLowerCase().includes('repar') ||
      (inc.mensaje || existing?.mensaje || '').toLowerCase().includes('cambio') ||
      (inc.mensaje || existing?.mensaje || '').toLowerCase().includes('ok')
    );
    // "Entregada" en CDE = En tránsito por transportadora solo para envíos de Danesa SA
    // que aún no estén entregadas ni reparadas en ASU ni recibidas en depósito.
    const enTransito = isEntregada && esDanesa && !esReparada && !tieneDetalleRep && !existing?.recibidoEnDeposito;

    if (existing) {
      const effectiveFechaEntregada = isFechaValida(inc.fechaEntregada)
        ? (inc.fechaEntregada || '').trim()
        : isFechaValida(existing.fechaEntregada)
          ? (existing.fechaEntregada || '').trim()
          : (inc.fechaEntregada || existing.fechaEntregada || '').trim();
      const effectiveMensaje = (inc.mensaje || '').trim() || (existing.mensaje || '').trim();
      const effectiveTipo =
        inc.tipoComponente && inc.tipoComponente.toUpperCase() !== 'GENERAL'
          ? inc.tipoComponente
          : existing.tipoComponente;
      const effectiveCliente = inc.cliente || existing.cliente;
      const effectiveMarca = inc.marca || existing.marca;
      const effectiveModelo = inc.modelo || existing.modelo;
      const effectiveSerial = inc.serial || existing.serial;

      const cambioEstado = !isSameNormalizedText(existing.estado, inc.estado);
      const cambioEntrega = (existing.fechaEntregada || '').trim() !== effectiveFechaEntregada;
      const cambioMensaje = !isSameNormalizedText(existing.mensaje, effectiveMensaje);
      const cambioMetadata =
        (existing.cliente || '') !== effectiveCliente ||
        (existing.marca || '') !== effectiveMarca ||
        (existing.modelo || '') !== effectiveModelo ||
        (existing.serial || '') !== effectiveSerial ||
        (existing.tipoComponente || '') !== effectiveTipo;

      if (cambioEstado || cambioEntrega || cambioMensaje) {
        if (enTransito && !existing.estado.toLowerCase().includes('entregada')) {
          totalEnTransitoNuevos++;
        }

        cambios.push({
          idOrden: inc.idOrden,
          cliente: effectiveCliente,
          equipo: `${effectiveMarca} ${effectiveModelo}`.trim() || effectiveTipo,
          estadoAnterior: existing.estado,
          estadoNuevo: inc.estado,
          fechaEntregada: effectiveFechaEntregada,
          esDanesa,
          enTransito,
        });

        const updatedRow: RecepcionCdeTicket = {
          ...existing,
          ...inc,
          codigoProducto: inc.codigoProducto || existing.codigoProducto,
          cliente: effectiveCliente,
          mensaje: effectiveMensaje,
          fechaIngreso: inc.fechaIngreso || existing.fechaIngreso,
          fechaEntregada: effectiveFechaEntregada,
          fechaVenta: inc.fechaVenta || existing.fechaVenta,
          tipoComponente: effectiveTipo,
          marca: effectiveMarca,
          modelo: effectiveModelo,
          serial: effectiveSerial,
          diasResolucion: calcularDiasResolucion(inc.fechaIngreso || existing.fechaIngreso, effectiveFechaEntregada),
          esDanesa,
          recibidoEnDeposito: Boolean(existing.rowKey && checkins[existing.rowKey] || existing.recibidoEnDeposito),
          esEstadoCambiadoReciente: true,
        };
        updatedList.push(updatedRow);
        changedOrNewTickets.push(updatedRow);
      } else if (cambioMetadata) {
        // Pulido silencioso de normalización (Título/Acrónimos/Mayúsculas en serial) sin alertas de cambio de estado
        totalSinCambios++;
        const polishedRow: RecepcionCdeTicket = {
          ...existing,
          cliente: effectiveCliente,
          tipoComponente: effectiveTipo,
          marca: effectiveMarca,
          modelo: effectiveModelo,
          serial: effectiveSerial,
          esDanesa,
        };
        updatedList.push(polishedRow);
        changedOrNewTickets.push(polishedRow);
      } else {
        totalSinCambios++;
        updatedList.push(existing);
      }
    } else {
      if (enTransito) {
        totalEnTransitoNuevos++;
      }

      cambios.push({
        idOrden: inc.idOrden,
        cliente: inc.cliente,
        equipo: `${inc.marca} ${inc.modelo}`.trim() || inc.tipoComponente,
        estadoAnterior: 'NO ESTABA EN CDE (NUEVA)',
        estadoNuevo: inc.estado,
        fechaEntregada: inc.fechaEntregada,
        esDanesa,
        enTransito,
      });

      const newRow: RecepcionCdeTicket = {
        ...inc,
        diasResolucion: calcularDiasResolucion(inc.fechaIngreso, inc.fechaEntregada),
        esDanesa,
        recibidoEnDeposito: false,
        esNuevoIngreso: true,
      };
      updatedList.push(newRow);
      changedOrNewTickets.push(newRow);
    }
  }

  currentTickets.forEach((t) => {
    const num = parseInt(t.idOrden, 10);
    if ((isNaN(num) || num >= SATI_MIN_ID_CDE) && !seenIds.has(t.idOrden)) {
      updatedList.push(t);
    }
  });

  saveCdeTickets(updatedList);

  if (typeof window !== 'undefined' && !options?.skipBackgroundSync && changedOrNewTickets.length > 0) {
    fetch('/api/db', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'BULK_UPDATE_CDE_CSV',
        tickets: changedOrNewTickets,
      }),
    }).catch((err) => console.error('[MySQL Error Bulk CDE CSV Update]', err));
  }

  const totalNuevas = cambios.filter((c) => c.estadoAnterior === 'NO ESTABA EN CDE (NUEVA)').length;
  const totalActualizadas = cambios.length - totalNuevas;

  return {
    updatedTickets: updatedList,
    totalFilasLeidas: incoming.length,
    totalActualizadas,
    totalNuevas,
    totalSinCambios,
    totalEnTransitoNuevos,
    cambios,
    changedOrNewTickets,
    depurationStats: classified.depurationStats,
  };
}

/**
 * Sube y sincroniza obligatoriamente el CSV de CDE en la base de datos MySQL en la nube (Railway).
 * Asegura que todos los técnicos y encargados vean los mismos datos en tiempo real.
 */
export async function sincronizarCdeCsvOnline(
  csvText: string | SatiCsvClassification,
  currentTickets?: RecepcionCdeTicket[]
): Promise<ResultadoCargaCdeCSV> {
  let base = currentTickets && currentTickets.length > 0
    ? currentTickets.filter((t) => {
        const n = parseInt(t.idOrden, 10);
        return isNaN(n) || n >= SATI_MIN_ID_CDE;
      })
    : getStoredCdeTickets();

  if (typeof window !== "undefined") {
    base = await fetchCdeTicketsFromMySQL({ throwOnError: true });
  }

  const resCalculo = procesarActualizacionCdeCSV(csvText, base, {
    skipBackgroundSync: true,
  });

  const totalRaw = resCalculo.depurationStats?.totalRawFilas ?? 0;
  if (resCalculo.totalFilasLeidas === 0 && totalRaw === 0) {
    throw new Error(
      "No se detectaron órdenes válidas en el archivo CSV/Excel. Verifique que sea exportado de SATI con columnas de orden."
    );
  }

  const ticketsToPersist = resCalculo.changedOrNewTickets ?? [];
  if (typeof window !== "undefined" && ticketsToPersist.length > 0) {
    // Dividir en lotes compactos de 400 órdenes (~250 KB/POST) para evitar truncamientos de body (>10 MB) en Next Middleware o proxies HTTP
    const SYNC_CHUNK_SIZE = 400;
    const totalChunks = Math.ceil(ticketsToPersist.length / SYNC_CHUNK_SIZE);
    let finalCloudData: RecepcionCdeTicket[] | null = null;

    for (let i = 0; i < totalChunks; i++) {
      const slice = ticketsToPersist
        .slice(i * SYNC_CHUNK_SIZE, (i + 1) * SYNC_CHUNK_SIZE)
        .map((t) => ({
          idOrden: t.idOrden,
          codigoProducto: t.codigoProducto || "",
          cliente: t.cliente,
          mensaje: t.mensaje || "",
          fechaIngreso: t.fechaIngreso || "",
          fechaEntregada: t.fechaEntregada || undefined,
          fechaVenta: t.fechaVenta || undefined,
          estado: t.estado || "En Asignacion",
          tipoComponente: t.tipoComponente || "General",
          modelo: t.modelo || "",
          marca: t.marca || "",
          serial: t.serial || "S/N",
          diasResolucion: t.diasResolucion ?? null,
          esDanesa: Boolean(t.esDanesa),
          recibidoEnDeposito: Boolean(t.recibidoEnDeposito),
        }));

      const isLastChunk = i === totalChunks - 1;
      const resp = await fetch("/api/db", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "BULK_UPDATE_CDE_CSV",
          tickets: slice,
          skipReturnData: !isLastChunk,
        }),
      });

      const json = await resp.json().catch(() => null);
      if (!resp.ok || !json?.ok) {
        throw new Error(json?.error || "Error al sincronizar con la base de datos MySQL en la nube (Railway).");
      }

      if (isLastChunk && Array.isArray(json.data) && json.data.length > 0) {
        finalCloudData = json.data as RecepcionCdeTicket[];
      }
    }

    if (finalCloudData && finalCloudData.length > 0) {
      const enriched = applyCloudCdeTickets(finalCloudData);
      return {
        ...resCalculo,
        updatedTickets: enriched,
      };
    }
  }

  return resCalculo;
}

